interface SignupForm {
  email: FormControl<string>;
  password: FormControl<string>;
}

readonly form = this.fb.group<SignupForm>({
  email: this.fb.control('', { nonNullable: true, validators: [Validators.required, Validators.email] }),
  password: this.fb.control('', { nonNullable: true, validators: [Validators.required, Validators.minLength(8)] }),
});

get emailInvalid(): boolean {
  const c = this.form.controls.email;
  return c.invalid && (c.dirty || c.touched);
}

// Template
// <input formControlName="email" [attr.aria-invalid]="emailInvalid" aria-describedby="email-error" />
// <span id="email-error" *ngIf="emailInvalid">Adresse email invalide</span>

